"""Generate a review composition, not the final poster/PDF."""
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

OUT=Path(__file__).resolve().parent
phase=np.linspace(0,1,501)
def smooth(x):return x*x*(3-2*x)
contraction=np.where(phase<.2,smooth(np.minimum(phase/.2,1)),np.where(phase<.5,1-smooth(np.clip((phase-.2)/.3,0,1)),0))
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False})
fig,ax=plt.subplots(figsize=(5.1,1.8),layout='constrained')
fig.patch.set_facecolor('#f5f8f7');ax.set_facecolor('#f5f8f7')
for lo,hi,color in [(0,.2,'#f4d9cf'),(.2,.5,'#dbe8e4'),(.5,1,'#e8edf1')]:ax.axvspan(lo,hi,color=color)
ax.plot(phase,contraction,color='#bb654d',lw=2.4)
ax.set(xlim=(0,1),ylim=(-.04,1.06),xlabel='Cycle phase (normalized)',ylabel='Contraction')
ax.set_xticks([0,.2,.5,1]);ax.set_yticks([0,1]);ax.grid(axis='y',alpha=.18)
fig.savefig(OUT/'illustrative-cycle.svg');plt.close(fig)

def wrap(body,view='0 0 500 200'):
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+view+'" role="img"><defs><marker id="arr" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="#367b82"/></marker></defs><style>text{font:13px system-ui;fill:#25454e}.label{font-size:12px}.caption{font-size:11px;fill:#5f7379}</style>'+body+'</svg>'
def jelly(x,y,s=1,c=0):
    w=60*(1-.18*c);h=35*(1+.28*c)
    b=f'<g transform="translate({x} {y}) scale({s})"><path d="M{-w} 0 C{-w} {-h*1.25} {w} {-h*1.25} {w} 0 Q0 24 {-w} 0Z" fill="#d9eeee" stroke="#398d94" stroke-width="2.2"/>'
    for xx in [-14,14]:
        for yy in [-17,-4]:
            b+=f'<path d="M{xx-6} {yy+3} C{xx-12} {yy-12} {xx+12} {yy-12} {xx+6} {yy+3}" fill="none" stroke="#c97994" stroke-width="3"/>'
    for i in range(11):
        xx=-w+6+i*(2*w-12)/10
        b+=f'<path d="M{xx} 5 Q{xx+5} 19 {xx+1} 29" fill="none" stroke="#80afb5" stroke-width="1.3"/>'
    for xx in [-21,-7,7,21]:
        b+=f'<path d="M{xx} 14 Q{xx-12} 34 {xx+2} 49 T{xx-4} 77" stroke="#7faeb5" stroke-width="4" fill="none"/>'
    return b+'</g>'

anatomy=wrap(jelly(157,66,1.25)+'''<path d="M157 20 H284 M228 64 H284 M92 99 H52 V134 M176 149 H284" stroke="#6b9398" fill="none"/><text x="295" y="24">Bell / apex</text><text x="295" y="67">Flexible margin</text><text x="17" y="153" class="label">Marginal tentacles</text><text x="295" y="152">Central oral arms</text><text x="114" y="185" class="caption">Four internal regions shown schematically [4]</text>''')
cycle=wrap(jelly(82,75,.70,0)+jelly(250,75,.70,1)+jelly(419,75,.70,0)+'''<text x="42" y="26">Open bell</text><text x="220" y="26">Contract</text><text x="377" y="26">Recover</text><path d="M138 66 H191 M305 66 H360" stroke="#367b82" stroke-width="2" marker-end="url(#arr)"/><rect x="20" y="149" width="92" height="15" rx="3" fill="#e4aa92"/><rect x="112" y="149" width="138" height="15" fill="#8fbeb5"/><rect x="250" y="149" width="230" height="15" rx="3" fill="#b6c6d0"/><text x="21" y="183" class="label">Contract</text><text x="144" y="183" class="label">Refill</text><text x="332" y="183" class="label">Coast / pause</text>''')
vortex=wrap(jelly(240,51,.8)+'''<ellipse cx="188" cy="147" rx="28" ry="18" fill="none" stroke="#b87765" stroke-width="2"/><ellipse cx="292" cy="147" rx="28" ry="18" fill="none" stroke="#b87765" stroke-width="2"/><path d="M240 127 V104" stroke="#367b82" stroke-width="3" marker-end="url(#arr)"/><path d="M173 133 Q193 123 211 143 M308 133 Q288 123 270 143" stroke="#b87765" stroke-width="2" fill="none"/><text x="15" y="117" class="label">Vortex ring</text><path d="M96 116 L163 141" stroke="#6b9398"/><text x="298" y="108" class="label">Continued propulsion</text><text x="144" y="185" class="caption">Cross-section schematic, not a flow simulation [1]</text>''')
margin=wrap('''<path d="M48 119 C48 15 258 15 258 119" fill="none" stroke="#98b6bd" stroke-width="3"/><path d="M67 119 C67 4 239 4 239 119" fill="none" stroke="#ce876d" stroke-width="3"/><path d="M48 119 Q55 137 81 128 M258 119 Q249 137 228 128" stroke="#367b82" stroke-width="5" fill="none"/><path d="M67 119 Q72 138 94 150 M239 119 Q232 138 211 150" stroke="#ce876d" stroke-width="5" fill="none"/><text x="296" y="63">Body changes shape.</text><text x="296" y="87">The edge bends too.</text><path d="M293 117 L241 138" stroke="#6b9398"/><text x="51" y="180" class="caption">Original explanatory profiles; not a digitized fit [2]</text>''')
turn=wrap('''<path d="M44 168 Q101 168 157 108 T393 80" stroke="#89a5ad" stroke-width="2" stroke-dasharray="6 5" fill="none" marker-end="url(#arr)"/>'''+jelly(99,103,.52)+f'<g transform="rotate(18 242 68)">{jelly(242,68,.52)}</g>'+f'<g transform="rotate(35 390 62)">{jelly(390,62,.52)}</g>'+'''<text x="20" y="24" class="label">Asymmetric timing can help produce a turn [3]</text><text x="206" y="185" class="caption">Orientation and travel can differ.</text>''')
for name,body in [('anatomy',anatomy),('cycle',cycle),('vortex',vortex),('margin',margin),('turn',turn)]:
    (OUT/(name+'.svg')).write_text(body)

panels=[('A','Anatomy','anatomy.svg','An oblate bell, a flexible edge, short marginal tentacles and longer central oral arms. Distinguish the fringe from the arms. [4]','SCHEMATIC'),
('B','Contract → recover → coast','cycle.svg','A quick active stroke, recovery of the bell and an interval before the next stroke. Phase widths here are an animation proposal. [1, 2]','SCHEMATIC / GAME'),
('C','Travel beyond the stroke','vortex.svg','The moving water beneath the bell can continue producing thrust after active bell motion has stopped. [1]','STUDY + SCHEMATIC'),
('D','A flexible margin','margin.svg','The margin does not simply follow the rest of the bell. Uniform scaling misses part of this deformation. [2]','STUDY + SCHEMATIC'),
('E','Turning and trailing','turn.svg','Different timing on opposite sides can accompany turning. Trailing appendage lag is a game choice, without a measured delay here. [3]','STUDY + GAME')]
cards=''
for letter,title,img,text,badge in panels:
    cards+=f'<section><div class="panelhead"><span>{letter}</span><h2>{title}</h2></div><img src="{img}" alt="{title} schematic"><p>{text}</p><div class="badge">{badge}</div></section>'
cards+='''<section><div class="panelhead"><span>F</span><h2>From observation to animation</h2></div><img class="plot" src="illustrative-cycle.svg" alt="Illustrative normalized contraction curve"><p><b>GAME proposal:</b> 20% contract · 30% recover · 50% coast. A 4.0 s player cycle; residents use separate pulse and drift clocks.</p><div class="badge">GAME · COMPUTED ILLUSTRATION, NOT EXPERIMENTAL DATA</div></section>'''
(OUT/'layout.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A3 Moon-jelly poster · review mockup</title><style>*{box-sizing:border-box}body{margin:0;background:#1b2b35;color:#233d45;font:14px/1.45 system-ui}.review{max-width:1122px;margin:20px auto;color:#d4e5e9;font-size:16px}.page{width:1122px;height:1587px;background:#fffefb;margin:20px auto;padding:42px;box-shadow:0 10px 50px #0005;overflow:hidden}header{border-top:10px solid #367b82;padding-top:20px;margin-bottom:24px}.kicker{letter-spacing:3px;color:#607b80;font-size:14px;font-weight:700}h1{font-size:44px;line-height:1.1;margin:12px 0 10px;font-weight:760;letter-spacing:-1px}.subtitle{font-size:19px;margin:0;color:#56747b}.legend{display:flex;gap:20px;margin-top:20px;font-size:12px;color:#506b73}.legend b{color:#25464d}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}section{height:308px;background:#f5f8f7;border:1px solid #d5e1df;border-radius:8px;padding:16px;position:relative}.panelhead{display:flex;align-items:center;gap:10px}.panelhead span{background:#367b82;color:#fff;font-weight:700;width:29px;height:29px;text-align:center;padding-top:3px;border-radius:4px}h2{font-size:19px;line-height:1.2;margin:0}section img{width:100%;height:173px;object-fit:contain;margin-top:10px}section img.plot{height:172px}p{margin:7px 0;font-size:14px;line-height:1.42}.badge{position:absolute;bottom:12px;left:16px;color:#7d6458;letter-spacing:.55px;font-size:10px;font-weight:750}.study{background:#edf3f3;border-left:5px solid #367b82;padding:15px 19px;margin-top:21px;display:grid;grid-template-columns:1fr 1fr;gap:27px}.study h3{font-size:16px;margin:0 0 5px}.study p{font-size:13px}footer{margin-top:18px;border-top:1px solid #a9bfbd;padding-top:13px;font-size:12px;line-height:1.45}footer b{font-size:13px}a{color:#286c76}footer .sources{display:grid;grid-template-columns:1fr 1fr;gap:8px 25px}.draft{margin-top:14px;color:#7d6458;font-size:11px}@page{size:A3 portrait;margin:0}@media print{body{background:white}.review{display:none}.page{margin:0;box-shadow:none;width:297mm;height:420mm}}</style><div class="review">LAYOUT REVIEW · A3 portrait, 297 × 420 mm · final print poster awaits approval.<br><a style="color:#a6d8df" href="../2026-10-02-jellyfish-biomechanics-poster.md">Read the production plan and sources</a></div><main class="page"><header><div class="kicker">JELLYFISH BIOMECHANICS · MOON-JELLY EXAMPLE</div><h1>MOON JELLY<br>THE ART OF THE PULSE</h1><p class="subtitle"><i>Aurelia aurita</i> · Contraction, recovery and coasting</p><div class="legend"><span><b>STUDY</b> checked observation + conditions</span><span><b>SCHEMATIC</b> explanatory drawing</span><span><b>GAME</b> chosen animation parameters</span></div></header><div class="grid">'''+cards+'''</div><div class="study"><div><h3>Natural timing varies [4]</h3><p><b>STUDY:</b> 0.24 ± 0.11 Hz in endogenous vertical swimming trials (n = 8; resting bell diameters 13–19 cm). This is a study-specific result, not a universal pulse rate.</p></div><div><h3>Keep the simplification visible</h3><p><b>GAME:</b> proposed radial contraction 18%, height change 28%. The compact rig does not reproduce full margin asymmetry or calculate the surrounding fluid flow.</p></div></div><footer><b>Primary research · original diagrams, no copied experimental figures</b><div class="sources"><div>[1] Gemmell et al. (2013), PNAS.<br><a href="https://doi.org/10.1073/pnas.1306983110">Passive energy recapture · DOI 10.1073/pnas.1306983110</a></div><div>[2] Villanueva, Vlachos &amp; Priya (2014), PLOS ONE.<br><a href="https://doi.org/10.1371/journal.pone.0098310">Flexible margins · DOI 10.1371/journal.pone.0098310</a></div><div>[3] Costello et al. (2024), Bioinspiration &amp; Biomimetics.<br><a href="https://doi.org/10.1088/1748-3190/ad1db8">Turning kinematics · DOI 10.1088/1748-3190/ad1db8</a></div><div>[4] Xu &amp; Dabiri (2020), Science Advances.<br><a href="https://doi.org/10.1126/sciadv.aaz3194">Anatomy / variable pulses · DOI 10.1126/sciadv.aaz3194</a></div></div><div class="draft">COMPOSITION MOCKUP · 2026-10-02 · explanatory geometry and proposed game curve; no fitted experimental trace.</div></footer></main></html>''')
